<script setup lang="ts">
import { computed } from 'vue'
const props=defineProps<{modelValue:any,canBrowse:boolean}>()
const emit=defineEmits<{'update:modelValue':[value:string[]],browse:[]}>()
const valid=computed(()=>props.modelValue===null||props.modelValue===undefined||(Array.isArray(props.modelValue)&&props.modelValue.every(x=>typeof x==='string')))
const items=computed<string[]>(()=>valid.value?(props.modelValue||[]):[])
function edit(event:Event){emit('update:modelValue',(event.target as HTMLTextAreaElement).value.split(/\r?\n/).filter(x=>x.length>0))}
</script>
<template><section class="file-exclusions" aria-label="单文件排除"><h3>排除单个文件中的变量 <small>已列 {{items.length}} 项</small></h3><p id="exclude-file-help" class="muted">例如只排除 Core/Src/syscalls.c 中定义的变量。文件仍参与构建和调用分析，它对其他变量的访问会保留。无需排除时留空。</p><p v-if="!valid" role="alert" class="banner error">原文 analysis.exclude_files 应是路径列表。请在高级YAML修复，或明确清空后重新选择。</p><label v-if="valid">排除文件路径（每行一个，相对固件目录）<textarea aria-label="排除文件路径" aria-describedby="exclude-file-help" :value="items.join('\n')" @input="edit" rows="3" placeholder="Core/Src/syscalls.c&#10;Core/Src/sysmem.c"/></label><div class="actions"><button type="button" :disabled="!canBrowse||!valid" @click="emit('browse')">从工程选择文件</button><button v-if="items.length||!valid" type="button" @click="emit('update:modelValue',[])">清空文件排除</button></div><p v-if="!canBrowse" class="muted">请先填写固件目录，再从工程中选择文件。</p><ul v-if="items.length" class="excluded-file-list"><li v-for="(path,index) in items" :key="index"><code>{{path}}</code><button type="button" :aria-label="'移除排除文件 '+path" @click="emit('update:modelValue',items.filter((_,i)=>i!==index))">移除</button></li></ul><p class="muted">路径中的空格和逗号会保留；保存并开始新扫描后生效。<code>analysis.exclude_files</code></p></section></template>
<style scoped>.file-exclusions{border-top:1px solid #d9e1ed;margin-top:16px;padding-top:8px}.file-exclusions h3 small{font-weight:400;font-size:12px;color:#64748b}.file-exclusions .muted{font-size:13px}.excluded-file-list{padding:0;list-style:none;max-height:240px;overflow:auto}.excluded-file-list li{display:flex;align-items:center;justify-content:space-between;gap:12px;border-bottom:1px solid #e7edf4;padding:4px}.excluded-file-list code{overflow-wrap:anywhere;min-width:0}.excluded-file-list button{flex-shrink:0;min-height:28px;padding:2px 8px}</style>
